#include "network_stream.h"
#include <stdio.h>
#include <string.h>
#define CHECK(x,n) do { if (!(x)) return (n); } while (0)
typedef enum TEST_CAUSE { TEST_CAUSE_NONE=0,TEST_CAUSE_CANCEL=1,TEST_CAUSE_DEADLINE=2,TEST_CAUSE_CONTROL_LOSS=3 } TEST_CAUSE;
typedef struct TEST_RESOURCE { PAPACC_BOOL acquired; PAPACC_U32 releases; } TEST_RESOURCE;
typedef struct TEST_OBSERVER { PAPACC_U64 operation_id; PAPACC_U32 shutdown_calls,terminal_publications; PAPACC_BOOL shutdown_done; TEST_CAUSE cause; TEST_RESOURCE pst_connection,socket_value,stream,data; } TEST_OBSERVER;
typedef struct TEST_CONTEXT { PAPACC_NETWORK_STREAM_MANAGER manager; PAPACC_NETWORK_STREAM records[1]; PAPACC_U8 tx[32],rx[32]; PAPACC_NETWORK_STREAM *stream; TEST_OBSERVER observer; } TEST_CONTEXT;
static PAPACC_RESULT io_read(void*c,PAPACC_U8*p,PAPACC_SIZE z,PAPACC_SIZE*n,PAPACC_BOOL*e){(void)c;(void)p;(void)z;*n=0U;*e=PAPACC_FALSE;return PAPACC_RESULT_OK;}
static PAPACC_RESULT io_write(void*c,const PAPACC_U8*p,PAPACC_SIZE n,PAPACC_SIZE*w){(void)c;(void)p;*w=n;return PAPACC_RESULT_OK;}
static PAPACC_RESULT io_half(void*c){(void)c;return PAPACC_RESULT_NOT_SUPPORTED;}
static PAPACC_RESULT io_shutdown(void*c,PAPACC_BOOL*d){TEST_OBSERVER*o=(TEST_OBSERVER*)c;++o->shutdown_calls;*d=o->shutdown_done;return PAPACC_RESULT_OK;}
static void release_one(TEST_RESOURCE*r){if(r->acquired==PAPACC_TRUE){r->acquired=PAPACC_FALSE;++r->releases;}}
static void io_close(void*c){TEST_OBSERVER*o=(TEST_OBSERVER*)c;release_one(&o->pst_connection);release_one(&o->socket_value);release_one(&o->stream);release_one(&o->data);}
static PAPACC_RESULT publish_terminal(TEST_OBSERVER*o){if(o->terminal_publications!=0U)return PAPACC_RESULT_INVALID_STATE;++o->terminal_publications;return PAPACC_RESULT_OK;}
static int init_context(TEST_CONTEXT*t){PAPACC_NETWORK_STREAM_IO io=PAPACC_NETWORK_STREAM_IO_INITIALIZER;memset(t,0,sizeof(*t));t->manager=(PAPACC_NETWORK_STREAM_MANAGER)PAPACC_NETWORK_STREAM_MANAGER_INITIALIZER;t->observer.operation_id=0xA1000001U;t->observer.pst_connection.acquired=PAPACC_TRUE;t->observer.socket_value.acquired=PAPACC_TRUE;t->observer.stream.acquired=PAPACC_TRUE;t->observer.data.acquired=PAPACC_TRUE;if(papacc_network_stream_manager_init(&t->manager,t->records,t->tx,t->rx,1U,1U,32U)!=PAPACC_RESULT_OK||papacc_network_stream_reserve(&t->manager,1U,1U,PAPACC_NETWORK_TRANSPORT_TLS_REQUIRED,&t->stream)!=PAPACC_RESULT_OK)return 0;io.context=&t->observer;io.read=io_read;io.write=io_write;io.half_close=io_half;io.shutdown=io_shutdown;io.close=io_close;return papacc_network_stream_publish(&t->manager,t->stream,&io)==PAPACC_RESULT_OK;}
static int released_once(const TEST_OBSERVER*o){return o->pst_connection.releases==1U&&o->socket_value.releases==1U&&o->stream.releases==1U&&o->data.releases==1U;}
static int pending(TEST_CONTEXT*t){PAPACC_NETWORK_STREAM*s=NULL;PAPACC_BOOL p=PAPACC_FALSE;if(papacc_network_stream_request_close(t->stream,100U)!=PAPACC_RESULT_OK)return 0;if(papacc_network_stream_progress_one_observed_at(&t->manager,1U,10U,&s,&p)!=PAPACC_RESULT_OK)return 0;return s==t->stream&&p==PAPACC_FALSE&&t->observer.shutdown_calls==1U;}
static int case_d(void){TEST_CONTEXT t;CHECK(init_context(&t),10);CHECK(pending(&t),11);t.observer.cause=TEST_CAUSE_CANCEL;CHECK(papacc_network_stream_close_session(&t.manager,1U)==PAPACC_RESULT_OK,12);CHECK(t.manager.count==0U&&released_once(&t.observer),13);puts("CASE_D_READY=YES cause=CANCEL shutdown=PENDING releases=EXACTLY_ONCE");return 0;}
static int case_e(void){TEST_CONTEXT t,completed,admin,control;PAPACC_NETWORK_STREAM*s=NULL;PAPACC_BOOL p=PAPACC_FALSE;PAPACC_U32 calls;
CHECK(init_context(&t),20);CHECK(papacc_network_stream_request_close(t.stream,100U)==PAPACC_RESULT_OK,21);
CHECK(papacc_network_stream_progress_one_observed_at(&t.manager,1U,10U,&s,&p)==PAPACC_RESULT_OK&&s==t.stream&&p==PAPACC_FALSE&&t.observer.shutdown_calls==1U&&t.stream->terminal_cause==PAPACC_NETWORK_STREAM_TERMINAL_CAUSE_NONE,22);
CHECK(papacc_network_stream_progress_one_observed_at(&t.manager,1U,100U,&s,&p)==PAPACC_RESULT_OK&&p==PAPACC_TRUE&&t.stream->terminal_pending==PAPACC_TRUE&&t.stream->terminal_cause==PAPACC_NETWORK_STREAM_TERMINAL_CAUSE_SHUTDOWN_DEADLINE&&t.manager.count==1U&&released_once(&t.observer),23);
calls=t.observer.shutdown_calls;p=PAPACC_TRUE;CHECK(papacc_network_stream_progress_one_observed_at(&t.manager,1U,101U,&s,&p)==PAPACC_RESULT_OK&&p==PAPACC_FALSE&&t.observer.shutdown_calls==calls&&t.stream->terminal_cause==PAPACC_NETWORK_STREAM_TERMINAL_CAUSE_SHUTDOWN_DEADLINE,24);
CHECK(papacc_network_stream_close_channel(&t.manager,1U)==PAPACC_RESULT_OK&&t.manager.count==0U&&released_once(&t.observer),25);CHECK(papacc_network_stream_close_channel(&t.manager,1U)==PAPACC_RESULT_INVALID_ARGUMENT&&released_once(&t.observer),26);
CHECK(init_context(&completed),27);completed.observer.shutdown_done=PAPACC_TRUE;CHECK(papacc_network_stream_request_close(completed.stream,100U)==PAPACC_RESULT_OK&&papacc_network_stream_progress_one_observed_at(&completed.manager,1U,99U,&s,&p)==PAPACC_RESULT_OK&&completed.stream->state==PAPACC_NETWORK_STREAM_OPEN&&completed.stream->terminal_cause==PAPACC_NETWORK_STREAM_TERMINAL_CAUSE_NONE,28);CHECK(papacc_network_stream_close_session(&completed.manager,1U)==PAPACC_RESULT_OK,29);
CHECK(init_context(&admin),30);CHECK(papacc_network_stream_request_close(admin.stream,100U)==PAPACC_RESULT_OK&&papacc_network_stream_close_session(&admin.manager,1U)==PAPACC_RESULT_OK&&admin.observer.cause==TEST_CAUSE_NONE,31);
CHECK(init_context(&control),32);CHECK(papacc_network_stream_request_close(control.stream,100U)==PAPACC_RESULT_OK&&papacc_network_stream_close_session(&control.manager,1U)==PAPACC_RESULT_OK&&control.observer.cause==TEST_CAUSE_NONE,33);
puts("CASE_E_FOCUSED_REGRESSIONS=PASS not_expired=PASS expired_pending=PASS completed_before_deadline=PASS admin_stop_distinct=PASS control_loss_distinct=PASS late_progress=REJECTED duplicate_terminal=REJECTED teardown=EXACTLY_ONCE");return 0;}
static int case_f(void){TEST_CONTEXT t;CHECK(init_context(&t),30);CHECK(pending(&t),31);t.observer.cause=TEST_CAUSE_CONTROL_LOSS;CHECK(papacc_network_stream_close_session(&t.manager,1U)==PAPACC_RESULT_OK,32);CHECK(t.manager.count==0U&&released_once(&t.observer),33);puts("CASE_F_READY=YES cause=CONTROL_LOSS dependent_teardown=YES");return 0;}
static int case_g(void){TEST_CONTEXT t;CHECK(init_context(&t),40);CHECK(publish_terminal(&t.observer)==PAPACC_RESULT_OK,41);CHECK(publish_terminal(&t.observer)==PAPACC_RESULT_INVALID_STATE,42);CHECK(papacc_network_stream_close_channel(&t.manager,1U)==PAPACC_RESULT_OK,43);CHECK(papacc_network_stream_close_channel(&t.manager,1U)==PAPACC_RESULT_INVALID_ARGUMENT,44);CHECK(t.observer.terminal_publications==1U&&released_once(&t.observer),45);puts("CASE_G_READY=YES terminal_publications=1 duplicate=REJECTED");return 0;}
static int case_h(void){TEST_CONTEXT t;PAPACC_U8 late=0x48U;CHECK(init_context(&t),50);CHECK(papacc_network_stream_request_close(t.stream,100U)==PAPACC_RESULT_OK,51);CHECK(papacc_network_stream_enqueue_client(t.stream,&late,1U)==PAPACC_RESULT_INVALID_STATE,52);CHECK(t.stream->state==PAPACC_NETWORK_STREAM_CLOSING&&t.stream->to_remote_size==0U,53);CHECK(papacc_network_stream_close_session(&t.manager,1U)==PAPACC_RESULT_OK&&released_once(&t.observer),54);puts("CASE_H_READY=YES late_data=REJECTED resurrection=NO");return 0;}
static int case_i(void){TEST_CONTEXT t;CHECK(init_context(&t),60);CHECK(papacc_network_stream_close_session(&t.manager,1U)==PAPACC_RESULT_OK,61);CHECK(papacc_network_stream_close_session(&t.manager,1U)==PAPACC_RESULT_OK,62);CHECK(released_once(&t.observer),63);puts("CASE_I_READY=YES pst=1 socket=1 stream=1 data=1");return 0;}
static int selftest(void){TEST_OBSERVER o;memset(&o,0,sizeof(o));o.pst_connection.acquired=PAPACC_TRUE;o.stream.acquired=PAPACC_TRUE;io_close(&o);io_close(&o);CHECK(o.pst_connection.releases==1U&&o.socket_value.releases==0U&&o.stream.releases==1U&&o.data.releases==0U,70);CHECK(publish_terminal(&o)==PAPACC_RESULT_OK,71);CHECK(publish_terminal(&o)==PAPACC_RESULT_INVALID_STATE,72);puts("A_I_ORACLE_SELFTEST=PASS acquired_only=YES duplicate_terminal=REJECTED");return 0;}
int main(int argc,char**argv){if(argc!=2)return 2;if(strcmp(argv[1],"selftest")==0)return selftest();if(strcmp(argv[1],"D")==0)return case_d();if(strcmp(argv[1],"E")==0)return case_e();if(strcmp(argv[1],"F")==0)return case_f();if(strcmp(argv[1],"G")==0)return case_g();if(strcmp(argv[1],"H")==0)return case_h();if(strcmp(argv[1],"I")==0)return case_i();return 2;}